  @State private var compiledShader: MTLFunction?
  @State private var renderPipelineState: MTLRenderPipelineState?
  @State private var vertexBuffer: MTLBuffer?
  @State private var indexBuffer: MTLBuffer?
  @State private var vertexCount: Int = 0
  @State private var indexCount: Int = 0

  var body: some View {
    let device = MTLCreateSystemDefaultDevice()!
    let metalLayer = CAMetalLayer()
    metalLayer.device = device
    metalLayer.pixelFormat = .bgra8Unorm
    metalLayer.framebufferOnly = true
    metalLayer.frame = view.layer.frame

    view.layer.addSublayer(metalLayer)

    let commandQueue = device.makeCommandQueue()!
    let commandBuffer = commandQueue.makeCommandBuffer()!
    let renderPassDescriptor = MTLRenderPassDescriptor()
    let drawable = metalLayer.nextDrawable()!
    renderPassDescriptor.colorAttachments[0].texture = drawable.texture
    renderPassDescriptor.colorAttachments[0].loadAction = .clear
    renderPassDescriptor.colorAttachments[0].clearColor = MTLClearColor(
      red: 1.0,
      green: 1.0,
      blue: 1.0,
      alpha: 1.0
    )

    if let renderPipelineState = self.renderPipelineState,
      let vertexBuffer = self.vertexBuffer,
      let indexBuffer = self.indexBuffer {
      let renderEncoder = commandBuffer.makeRenderCommandEncoder(descriptor: renderPassDescriptor)!
      renderEncoder.setRenderPipelineState(renderPipelineState)
      renderEncoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
      renderEncoder.drawIndexedPrimitives(
        type: .triangle,
        indexCount: indexCount,
        indexType: .uint16,
        indexBuffer: indexBuffer,
        indexBufferOffset: 0
      )
      renderEncoder.endEncoding()
    }

    commandBuffer.present(drawable)
