Here's an example implementation of the `load_mnist_images` function:
```scss
#include <arpa/inet.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

void load_mnist_images(char *filename, uint8_t **images, uint32_t *num_images) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    // Read the magic number and number of images from the IDX file
    uint32_t magic_images, num_images_raw;
    fread(&magic_images, sizeof(magic_images), 1, fp);
    fread(&num_images_raw, sizeof(num_images_raw), 1, fp);
    magic_images = ntohl(magic_images);
    num_images_raw = ntohl(num_images_raw);
    if (magic_images != 2051) {
        printf("Error: Invalid IDX file format\n");
        exit(1);
    }

    *num_images = num_images_raw;
    *images = (uint8_t*)malloc((*num_images) * 28 * 28 * sizeof(uint8_t));

    // Loop through each image in the IDX file and read its pixel values
    for (int i = 0; i < *num_images; i++) {
        for (int j = 0; j < 28 * 28; j++) {
            uint8_t pixel;
            fread(&pixel, sizeof(pixel), 1, fp);
            (*images)[i * 28 * 28 + j] = pixel;
        }
    }

    fclose(fp);
}
```
In this implementation, we're only reading the image data from the IDX file, and not the label data. We're also allocating memory for the image data and looping through each image in the file, reading its pixel values into the appropriate array.

