public:
    User(std::string name) : name_(name) {}
    std::string name() const { return name_; }
private:
    std::string name_;
};

// Domain services
class UserRepository {
public:
    virtual std::vector<User> getUsers() = 0;
    virtual void saveUser(const User& user) = 0;
};

class UserService {
public:
    UserService(std::shared_ptr<UserRepository> userRepository) 
        : userRepository_(userRepository) {}
    std::vector<User> getUsers() { return userRepository_->getUsers(); }
    void saveUser(const User& user) { userRepository_->saveUser(user); }
private:
    std::shared_ptr<UserRepository> userRepository_;
};

// Application component
class UserController {
public:
    UserController(std::shared_ptr<UserService> userService) 
        : userService_(userService) {}
    void listUsers() {
        std::vector<User> users = userService_->getUsers();
        for (const auto& user : users) {
            std::cout << user.name() << std::endl;
        }
    }
    void addUser(std::string name) {
        User user(name);
        userService_->saveUser(user);
    }
private:
    std::shared_ptr<UserService> userService_;
};

// Infrastructure component
class InMemoryUserRepository : public UserRepository {
public:
    std::vector<User> getUsers() override { return users_; }
