The shopping cart aggregate root can be implemented using CRTP (Curiously Recurring Template Pattern) and the Visitor pattern in C++17. Here's an example implementation:
```c++
// Base class for the visitor
template <typename Derived>
class ShoppingCartVisitor {
public:
    // Visit method for visiting items
    template <typename Item>
    void visit(Item& item) {
        static_cast<Derived*>(this)->visit(item);
    }
};

// Aggregate root for the shopping cart
template <typename Derived>
class ShoppingCart {
public:
    // Add an item to the cart
    template <typename Item>
    void addItem(Item item) {
        items_.emplace_back(std::move(item));
    }

    // Remove an item from the cart
    template <typename Item>
    void removeItem(Item item) {
        items_.erase(std::remove(items_.begin(), items_.end(), std::move(item)),
                     items_.end());
    }

    // Accept a visitor to perform an operation on each item
    template <typename Visitor>
    void accept(Visitor& visitor) {
        for (auto& item : items_) {
            visitor.visit(item);
        }
        static_cast<Derived*>(this)->accept(visitor);
    }

private:
    std::vector<Item> items_;
};
