```javascript
// Add the following code to your existing game.js file

class Bot {
  constructor(position) {
    this.position = position;
  }

  move(newPosition) {
    removeElement(this.position, 'bot');
    setElement(newPosition, 'bot');
    this.position = newPosition;
  }
}

function createBots(numBots) {
  const bots = [];
  for (let i = 0; i < numBots; i++) {
    let botPosition;
    do {
      botPosition = Math.floor(Math.random() * boardSize * boardSize);
    } while (cells[botPosition].classList.length > 1); // Ensure the position is not occupied

    const bot = new Bot(botPosition);
    setElement(bot.position, 'bot');
    bots.push(bot);
  }
  return bots;
}

function moveBotsRandomly(bots) {
  bots.forEach((bot) => {
    const possibleMoves = [
      bot.position + 1,
      bot.position - 1,
      bot.position + boardSize,
      bot.position - boardSize,
    ];
    const allowedMoves = possibleMoves.filter((move) => isMoveAllowed(move));
    const randomMove = allowedMoves[Math.floor(Math.random() * allowedMoves.length)];
    bot.move(randomMove);
  });
}

function checkBotCollision(player, bots) {
  for (const bot of bots) {
    if (player.position === bot.position) {
      stopGame();
      return true;
    }
  }
  return false;
}
