def por_issuance(request):
    if request.method == 'POST':
        form = PorForm(request.POST)
        if form.is_valid():
            por = form.save(commit=False)
            issued_to_id = request.POST['issued_to']
            issued_to = Resident.objects.get(id=issued_to_id)
