def por_report(request):
    wards = Resident.objects.values_list('ward', flat=True).distinct()
    addresses = Resident.objects.values_list('address', flat=True).distinct()
    residents = Resident.objects.all()
    return render(request, 'por/por_report.html', {'wards': wards, 'addresses': addresses, 'residents': residents})

def account_notifications(request, account_number):
    account = MunicipalAccount.objects.get(account_number=account_number)
    residents = Resident.objects.filter(municipal_account=account)
    por_list = []
    for resident in residents:
        por_list.extend(list(resident.issued_pors.all()))
    por_list.sort(key=lambda por: por.issued_on, reverse=True)
    return render(request, 'por/account_notifications.html', {'por_list': por_list})
