import { Controller, Post, Request, Response, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { AuthService } from './auth.service';
import { User } from '../user/user.entity';

@Controller('auth')
export class AuthController {
  constructor(private authService: AuthService) {}

  @UseGuards(AuthGuard('local'))
  @Post('login')
  async login(@Request() req, @Response({ passthrough: true }) res): Promise<{ access_token: string }> {
    const { access_token } = await this.authService.login(req.user as User);
    res.cookie('access_token', access_token, { httpOnly: true });
    return { access_token };
  }

  @UseGuards(AuthGuard('jwt'))
  @Post('logout')
  async logout(@Request() req, @Response({ passthrough: true }) res): Promise<void> {
    res.clearCookie('access_token');
  }
}
```
Here, we are using the `@Response({ passthrough: true })` decorator to enable cookie support. In the `login` method, we are setting the `access_token` cookie with the token value returned by the `AuthService`. In the `logout` method, we are clearing the `access_token` cookie.

That's it! Now, the JWT token will be stored as an HttpOnly cookie and sent along with every request to the server. You can access the token in the server using the `req.cookies.access_token` property.

