      <ul>
        {repos.map((repo) => (
          <li key={repo.id}>{repo.name}</li>
        ))}
      </ul>
    </div>
  );
}

// Second component to search for string in repositories
function StringSearch({ repos, searchString }) {
  const [matches, setMatches] = useState([]);

  useEffect(() => {
    const filteredRepos = repos.filter((repo) =>
      repo.name.includes(searchString)
    );
    setMatches(filteredRepos);
  }, [repos, searchString]);

  return (
    <div>
      <h2>Repositories containing "{searchString}":</h2>
      <ul>
        {matches.map((repo) => (
          <li key={repo.id}>{repo.name}</li>
        ))}
      </ul>
    </div>
  );
