        for (int i = 0; i < Messages.Length; i++)
        {
            Debug.Log(Messages[i]);
        }
    }
}
```
This job logs a list of messages to the console when executed.

Next, let's create a system that schedules the job to run:
```csharp
using Unity.Burst;
using Unity.Collections;
using Unity.Entities;
using Unity.Jobs;
using UnityEngine;

public class LogSystem : SystemBase
{
    private JobHandle _jobHandle;

    protected override void OnUpdate()
    {
        var messages = new NativeArray<string>(1, Allocator.TempJob);
        messages[0] = "Hello from DOTS!";

        var job = new LogJob
        {
            Messages = messages
        };

        _jobHandle = job.Schedule();

        job.Complete();

        messages.Dispose();
    }

    protected override void OnDestroy()
    {
        _jobHandle.Complete();
    }
}
```
This system creates a list of messages, schedules the `LogJob` to run, and waits for it to complete.

