fn play_sound(sound_data: &[u8]) {
    let device = rodio::default_output_device().unwrap();
    let source = rodio::Decoder::new(Cursor::new(sound_data)).unwrap();
    rodio::play_raw(&device, source.convert_samples());
}

fn setup_system_tray_icon() -> NOTIFYICONDATAW {
    let hinstance = unsafe { winapi::um::libloaderapi::GetModuleHandleW(null_mut()) };
    let hicon = unsafe { LoadIconW(hinstance, winapi::um::winuser::IDI_APPLICATION) };

    let class_name = OsStr::new("system_tray_icon")
        .encode_wide()
        .chain(std::iter::once(0))
        .collect::<Vec<u16>>();

    let mut nid: NOTIFYICONDATAW = unsafe { std::mem::zeroed() };
    nid.cbSize = std::mem::size_of::<NOTIFYICONDATAW>() as u32;
    nid.hWnd = unsafe { CreateWindowExW(0, class_name.as_ptr(), null_mut(), 0, 0, 0, 0, 0, null_mut(), null_mut(), hinstance, null_mut()) };
    nid.uID = 0;
    nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_APP;
    nid.hIcon = hicon;
    nid.szTip[0] = 'T' as wchar_t;
    nid.szTip[1] = 'r' as wchar_t;
    nid.szTip[2] = 'a' as wchar_t;
    nid.szTip[3] = 'y' as wchar_t;
    nid.szTip[4] = ' ' as wchar_t;
    nid.szTip[5] = 'I' as wchar_t;
    nid.szTip[6] = 'c' as wchar_t;
    nid.szTip[7] = 'o' as wchar_t;
    nid.szTip[8] = 'n' as wchar_t;
    nid.szTip[9] = 0;

    unsafe {
        Shell_NotifyIconW(NIM_ADD, &nid);
    }

    nid
}

fn main() {
    let (tx, rx) = channel::<()>();

    // Register the hotkey (Ctrl+Shift+K)
    unsafe {
        RegisterHotKey(
            null_mut(),
            HOTKEY_ID,
            winapi::um::winuser::MOD_CONTROL | winapi::um::winuser::MOD_SHIFT,
            'K' as u32,
        );
    }

    // System tray icon setup
    let icon_data = setup_system_tray_icon();

    // Message loop
    unsafe {
        let mut msg = std::mem::zeroed();
        while GetMessageW(&mut msg, 0 as HWND, 0, 0) > 0 {
            match msg.message {
                WM_HOTKEY => {
                    if msg.wParam == HOTKEY_ID as WPARAM {
                        play_sound(SOUND_DATA);
                    }
                }
                _ => (),
            }
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }

        // Cleanup
        Shell_NotifyIconW(NIM_DELETE, &icon_data);
        UnregisterHotKey(null_mut(), HOTKEY_ID);
    }
}
