```typescript
import React, { useState } from 'react';
import { useCombobox } from 'downshift';

interface Props {
  searchEmails: (prefix: string) => Promise<string[]>;
}

const EmailInput: React.FC<Props> = ({ searchEmails }) => {
  const [inputValue, setInputValue] = useState('');
  const [emails, setEmails] = useState<string[]>([]);

  const handleInputChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setInputValue(value);
    const results = await searchEmails(value);
    setEmails(results);
  };

  const {
    isOpen,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    getItemProps,
    highlightedIndex,
  } = useCombobox({
    items: emails,
    onInputValueChange: handleInputChange,
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} type="email" placeholder="Email" />
      <ul {...getMenuProps()}>
        {isOpen &&
          emails.map((email, index) => (
            <li
              {...getItemProps({ item: email, index })}
              key={`${email}${index}`}
              style={{
                backgroundColor: highlightedIndex === index ? '#bde4ff' : 'white',
                fontWeight: highlightedIndex === index ? 'bold' : 'normal',
              }}
            >
              {email}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInput;
```
In this implementation, the `EmailInput` component takes in a `searchEmails` function as a prop, which is an asynchronous function that returns a Promise of an array of email strings that match the given prefix.

The `EmailInput` component uses the `useState` hook to maintain the current input value and the list of matching email strings. The `handleInputChange` function is called whenever the input value changes, and it sets the current input value and updates the list of matching email strings by calling the `searchEmails` function.

The `useCombobox` hook from the Downshift library is used to manage the autocomplete behavior of the email input field. It takes in an array of items (in this case, the list of matching email strings) and an `onInputValueChange` callback function (in this case, the `handleInputChange` function). It returns a set of props that are spread onto the input field and the list of matching email strings.

The `getItemProps` function is called for each item in the list of matching email strings, and it returns a set of props that are spread onto each list item. This includes an `item` prop that contains the email string, an `index` prop that contains the index of the item in the list, and event handlers for the `onClick` and `onKeyDown` events.

Overall, this implementation provides a simple email input field that autocompletes as the user types, and uses an asynchronous function to retrieve the matching email strings.

