    const value = event.target.value;
    setInputValue(value);
    const results = await searchEmails(value);
    setEmails(results);
  };

  const handleRemoveItem = (index: number) => {
    const newEmails = [...emails];
    newEmails.splice(index, 1);
    setEmails(newEmails);
  };

  const {
    isOpen,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    getItemProps,
    highlightedIndex,
