        {emails.map((email, index) => (
          <li key={`${email}${index}`} {...getSelectedItemProps({ item: email, index })}>
            {email}
            <button onClick={() => handleRemoveItem(index)}>Remove</button>
          </li>
        ))}
      </ul>
      <input {...getInputProps()} type="email" placeholder="Enter email" />
