    jpeg_compress_struct cinfo;
    jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &jpeg_buffer, &jpeg_buffer_size);
    cinfo.image_width = image_size;
    cinfo.image_height = image_size;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[(cinfo.image_height - 1 - cinfo.next_scanline) * image_size * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    std::ofstream file("qrcode.jpg", std::ios::binary);
    file.write((char*)jpeg_buffer.data(), jpeg_buffer.size());
    file.close();

    return 0;
}
