import { customElement, html, FASTElement, attr } from "@microsoft/fast-element";

@customElement("text-input")
export class TextInputComponent extends FASTElement {
  @attr({ mode: "boolean" }) public required = false;
  @attr({ mode: "boolean" }) public disabled = false;
  @attr public value = "";
  @attr public label = "";
  @attr public error = "";
  @attr public pattern = "";

  private input: HTMLInputElement;

  connectedCallback() {
    super.connectedCallback();
    this.input = this.shadowRoot?.querySelector("input") as HTMLInputElement;
    this.input.addEventListener("input", this.handleInputChange);
  }

  handleInputChange = (event: Event) => {
    this.value = (event.target as HTMLInputElement).value;
  };

  public validate(): boolean {
    if (this.required && this.value === "") {
      this.error = "This field is required";
      return false;
    }
    if (this.pattern && this.value !== "") {
      const regex = new RegExp(this.pattern);
      if (!regex.test(this.value)) {
        this.error = "Invalid input";
        return false;
      }
    }
    this.error = "";
    return true;
  }

  public render() {
    return html`
      <div class="form-field">
        <label for="input">${this.label}</label>
        <input
          id="input"
          type="text"
          .value=${this.value}
          ?required=${this.required}
          ?disabled=${this.disabled}
          pattern=${this.pattern}
        />
        ${this.error &&
        html`<div class="error-message" role="alert">${this.error}</div>`}
      </div>
    `;
  }
}
```
