```typescript
import * as React from 'react';
import styles from './AudioRecorderWebPart.module.scss';
import { IAudioRecorderWebPartProps } from './IAudioRecorderWebPartProps';

export default class AudioRecorderWebPart extends React.Component<IAudioRecorderWebPartProps> {

  private mediaRecorder: MediaRecorder;
  private recordedChunks: Blob[];

  constructor(props: IAudioRecorderWebPartProps) {
    super(props);
    this.recordedChunks = [];
  }

  private async startRecording() {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    this.mediaRecorder = new MediaRecorder(stream);
    this.mediaRecorder.addEventListener('dataavailable', (event: BlobEvent) => {
      if (event.data.size > 0) {
        this.recordedChunks.push(event.data);
      }
    });
    this.mediaRecorder.start();
  }

  private async stopRecording() {
    return new Promise((resolve) => {
      this.mediaRecorder.addEventListener('stop', () => {
        const recordedBlob = new Blob(this.recordedChunks, { type: 'audio/mp3' });
        this.uploadAudio(recordedBlob);
        this.recordedChunks = [];
        resolve();
      });
      this.mediaRecorder.stop();
    });
  }

  private async uploadAudio(blob: Blob) {
    const siteUrl = this.props.siteUrl;
    const listName = this.props.listName;
    const fileName = `audio_${new Date().toISOString()}.mp3`;
    const fileUrl = `${siteUrl}/_api/web/lists/getByTitle('${listName}')/RootFolder/Files/add(url='${fileName}',overwrite=true)`;
    const authToken = await this.props.context.aadTokenProviderFactory.getTokenProvider().getToken('https://graph.microsoft.com');
    const headers = new Headers({
      'Authorization': `Bearer ${authToken}`,
      'Content-Type': 'audio/mp3',
    });
    const response = await fetch(fileUrl, {
      method: 'POST',
      headers: headers,
      body: blob,
    });
    if (!response.ok) {
      console.error('Failed to upload audio file:', response.statusText);
    }
  }

  public render(): React.ReactElement<IAudioRecorderWebPartProps> {
    return (
      <div className={styles.audioRecorderWebPart}>
        <h1>Record Audio</h1>
        <button onClick={() => this.startRecording()}>Start Recording</button>
        <button onClick={() => this.stopRecording()}>Stop Recording</button>
      </div>
    );
  }
}
```
