class SQLQueryBuilder {
  constructor() {
    this.query = "";
  }

  select(fields) {
    this.query += `SELECT ${fields.join(", ")} `;
    return this;
  }

  from(table) {
    this.query += `FROM ${table} `;
    return this;
  }

  where(conditions) {
    this.query += `WHERE ${conditions.join(" AND ")} `;
    return this;
  }

  groupBy(fields) {
    this.query += `GROUP BY ${fields.join(", ")} `;
    return this;
  }

  having(conditions) {
    this.query += `HAVING ${conditions.join(" AND ")} `;
    return this;
  }

  orderBy(fields) {
    this.query += `ORDER BY ${fields.join(", ")} `;
    return this;
  }

  limit(number) {
    this.query += `LIMIT ${number} `;
    return this;
  }

  offset(number) {
    this.query += `OFFSET ${number} `;
    return this;
  }

  build() {
    return this.query.trim();
  }
}

